import React from 'react';
import clsx from 'clsx';
import useDocusaurusContext from '@docusaurus/useDocusaurusContext';
import {useThemeConfig, useColorMode} from '@docusaurus/theme-common';
import type {ThemeConfig} from '@docusaurus/theme-common';
import {
  parseLanguage,
  useCodeWordWrap,
} from '@docusaurus/theme-common/internal';
import Highlight, {defaultProps, type Language} from 'prism-react-renderer';
import Line from '@theme/CodeBlock/Line';
import CopyButton from '@theme/CodeBlock/CopyButton';
import WordWrapButton from '@theme/CodeBlock/WordWrapButton';
import Container from '@theme/CodeBlock/Container';
import type {Props} from '@theme/CodeBlock/Content/String';

import styles from './styles.module.css';

export default function CodeBlockString({
  children,
  className: blockClassName = '',
  metastring,
  title: titleProp,
  showLineNumbers: showLineNumbersProp,
  language: languageProp,
}: Props): JSX.Element {
  const {
    prism: {defaultLanguage, magicComments},
  } = useThemeConfig();
  const language =
    languageProp ?? parseLanguage(blockClassName) ?? defaultLanguage;
  const wordWrap = useCodeWordWrap();
  const {colorMode} = useColorMode();
  const docusaurusContext = useDocusaurusContext();
  const siteThemeConfig = docusaurusContext.siteConfig
    .themeConfig as ThemeConfig;
  const prismSettings = siteThemeConfig.prism;
  const lightModeTheme = prismSettings.theme;
  const configuredDarkTheme = prismSettings.darkTheme;
  let prismTheme = lightModeTheme;
  if (colorMode === 'dark') {
    if (configuredDarkTheme) {
      prismTheme = configuredDarkTheme;
    } else {
      prismTheme = lightModeTheme;
    }
  } else {
    prismTheme = lightModeTheme;
  }

  const codeBlockTitleRegex = /title=(?<quote>["'])(?<title>.*?)\1/;
  let title = '';
  if (metastring) {
    const titleMatch = metastring.match(codeBlockTitleRegex);
    const extractedTitle = titleMatch?.groups?.title;
    if (typeof extractedTitle === 'string') {
      title = extractedTitle;
    }
  }
  if (!title) {
    if (titleProp) {
      title = titleProp;
    }
  }

  let showLineNumbers = false;
  if (typeof showLineNumbersProp === 'boolean') {
    showLineNumbers = showLineNumbersProp;
  } else if (metastring) {
    showLineNumbers = metastring.includes('showLineNumbers');
  }

  let code = children.replace(/\n$/, '');
  const lineClassNames: {[lineIndex: number]: string[]} = {};
  const metastringLinesRangeRegex = /\{(?<range>[\d,-]+)\}/;
  let parsedMetastringRange = false;
  const inclusiveRangeSeparators = ['-', '..', '\u2025'];
  const numericRangePattern =
    /^(-?\d+)(-|\.\.\.?|\u2025|\u2026|\u22EF)(-?\d+)$/;

  if (metastring && metastringLinesRangeRegex.test(metastring)) {
    const rangeMatch = metastring.match(metastringLinesRangeRegex);
    const linesRange = rangeMatch?.groups?.range;
    if (linesRange) {
      if (magicComments.length === 0) {
        throw new Error(
          `A highlight range has been given in code block's metastring (\`\`\` ${metastring}), but no magic comment config is available. Docusaurus applies the first magic comment entry's className for metastring ranges.`,
        );
      }
      const metastringRangeClassName = magicComments[0]!.className;
      const parsedRange: number[] = [];
      const rangeParts = linesRange.split(',');
      for (let partIndex = 0; partIndex < rangeParts.length; partIndex += 1) {
        const part = rangeParts[partIndex]!.trim();
        if (!part) {
          continue;
        }
        if (/^-?\d+$/.test(part)) {
          parsedRange.push(parseInt(part, 10));
        } else {
          const rangePair = part.match(numericRangePattern);
          if (rangePair) {
            const lhsToken = rangePair[1];
            const rhsToken = rangePair[3];
            const sep = rangePair[2];
            if (lhsToken && rhsToken && sep) {
              let lhs = parseInt(lhsToken, 10);
              let rhs = parseInt(rhsToken, 10);
              const incr = lhs < rhs ? 1 : -1;
              if (inclusiveRangeSeparators.includes(sep)) {
                rhs += incr;
              }
              for (let cursor = lhs; cursor !== rhs; cursor += incr) {
                parsedRange.push(cursor);
              }
            }
          }
        }
      }
      for (let rangeIndex = 0; rangeIndex < parsedRange.length; rangeIndex += 1) {
        const highlightedLine = parsedRange[rangeIndex]!;
        if (highlightedLine > 0) {
          lineClassNames[highlightedLine - 1] = [metastringRangeClassName];
        }
      }
      parsedMetastringRange = true;
    }
  }

  if (!parsedMetastringRange && language !== undefined) {
    const commentPatterns = {
      js: {start: '\\/\\/', end: ''},
      jsBlock: {start: '\\/\\*', end: '\\*\\/'},
      jsx: {start: '\\{\\s*\\/\\*', end: '\\*\\/\\s*\\}'},
      bash: {start: '#', end: ''},
      html: {start: '<!--', end: '-->'},
      lua: {start: '--', end: ''},
      wasm: {start: '\\;\\;', end: ''},
      tex: {start: '%', end: ''},
    } as const;
    type CommentType = keyof typeof commentPatterns;
    const commentTypeByLanguage: {[lang: string]: CommentType[]} = {
      js: ['js', 'jsBlock'],
      javascript: ['js', 'jsBlock'],
      ts: ['js', 'jsBlock'],
      typescript: ['js', 'jsBlock'],
      jsx: ['js', 'jsBlock', 'jsx'],
      tsx: ['js', 'jsBlock', 'jsx'],
      html: ['js', 'jsBlock', 'html'],
      python: ['bash'],
      py: ['bash'],
      bash: ['bash'],
      markdown: ['html', 'jsx', 'bash'],
      md: ['html', 'jsx', 'bash'],
      tex: ['tex'],
      latex: ['tex'],
      matlab: ['tex'],
      lua: ['lua'],
      haskell: ['lua'],
      sql: ['lua'],
      wasm: ['wasm'],
    };
    const selectedCommentTypes =
      commentTypeByLanguage[language] ??
      (['js', 'jsBlock', 'jsx', 'bash', 'html'] as CommentType[]);

    const directiveTokens: string[] = [];
    for (
      let directiveIndex = 0;
      directiveIndex < magicComments.length;
      directiveIndex += 1
    ) {
      const magicComment = magicComments[directiveIndex]!;
      if (magicComment.line) {
        directiveTokens.push(magicComment.line);
      }
      if (magicComment.block) {
        if (magicComment.block.start) {
          directiveTokens.push(magicComment.block.start);
        }
        if (magicComment.block.end) {
          directiveTokens.push(magicComment.block.end);
        }
      }
    }

    const commentPatternPieces: string[] = [];
    for (
      let commentTypeIndex = 0;
      commentTypeIndex < selectedCommentTypes.length;
      commentTypeIndex += 1
    ) {
      const commentType = selectedCommentTypes[commentTypeIndex]!;
      const pattern = commentPatterns[commentType];
      const joinedDirectives = directiveTokens.join('|');
      const piece = `(?:${pattern.start}\\s*(${joinedDirectives})\\s*${pattern.end})`;
      commentPatternPieces.push(piece);
    }
    const directiveRegex = new RegExp(
      `^\\s*(?:${commentPatternPieces.join('|')})\\s*$`,
    );

    const lines = code.split('\n');
    const blocks: {[className: string]: {start: number; range: string}} = {};
    const lineToClassName: {[comment: string]: string} = {};
    const blockStartToClassName: {[comment: string]: string} = {};
    const blockEndToClassName: {[comment: string]: string} = {};
    for (
      let mappingIndex = 0;
      mappingIndex < magicComments.length;
      mappingIndex += 1
    ) {
      const magicComment = magicComments[mappingIndex]!;
      blocks[magicComment.className] = {start: 0, range: ''};
      if (magicComment.line) {
        lineToClassName[magicComment.line] = magicComment.className;
      }
      if (magicComment.block) {
        if (magicComment.block.start) {
          blockStartToClassName[magicComment.block.start] =
            magicComment.className;
        }
        if (magicComment.block.end) {
          blockEndToClassName[magicComment.block.end] = magicComment.className;
        }
      }
    }

    for (let lineNumber = 0; lineNumber < lines.length; ) {
      const line = lines[lineNumber]!;
      const match = line.match(directiveRegex);
      if (!match) {
        lineNumber += 1;
        continue;
      }
      let directive: string | undefined;
      for (let matchIndex = 1; matchIndex < match.length; matchIndex += 1) {
        const item = match[matchIndex];
        if (item !== undefined) {
          directive = item;
          break;
        }
      }
      if (directive !== undefined) {
        const lineClassName = lineToClassName[directive];
        const blockStartClassName = blockStartToClassName[directive];
        const blockEndClassName = blockEndToClassName[directive];
        if (lineClassName) {
          blocks[lineClassName]!.range += `${lineNumber},`;
        } else if (blockStartClassName) {
          blocks[blockStartClassName]!.start = lineNumber;
        } else if (blockEndClassName) {
          const blockState = blocks[blockEndClassName]!;
          blockState.range += `${blockState.start}-${lineNumber - 1},`;
        }
      }
      lines.splice(lineNumber, 1);
    }
    code = lines.join('\n');

    const blockEntries = Object.entries(blocks);
    for (
      let entryIndex = 0;
      entryIndex < blockEntries.length;
      entryIndex += 1
    ) {
      const [className, blockState] = blockEntries[entryIndex]!;
      const parsedBlockRange: number[] = [];
      const blockRangeParts = blockState.range.split(',');
      for (
        let partIndex = 0;
        partIndex < blockRangeParts.length;
        partIndex += 1
      ) {
        const part = blockRangeParts[partIndex]!.trim();
        if (!part) {
          continue;
        }
        if (/^-?\d+$/.test(part)) {
          parsedBlockRange.push(parseInt(part, 10));
        } else {
          const rangePair = part.match(numericRangePattern);
          if (rangePair) {
            const lhsToken = rangePair[1];
            const rhsToken = rangePair[3];
            const sep = rangePair[2];
            if (lhsToken && rhsToken && sep) {
              let lhs = parseInt(lhsToken, 10);
              let rhs = parseInt(rhsToken, 10);
              const incr = lhs < rhs ? 1 : -1;
              if (inclusiveRangeSeparators.includes(sep)) {
                rhs += incr;
              }
              for (let cursor = lhs; cursor !== rhs; cursor += incr) {
                parsedBlockRange.push(cursor);
              }
            }
          }
        }
      }
      for (
        let rangeIndex = 0;
        rangeIndex < parsedBlockRange.length;
        rangeIndex += 1
      ) {
        const highlightedLine = parsedBlockRange[rangeIndex]!;
        if (lineClassNames[highlightedLine]) {
          lineClassNames[highlightedLine]!.push(className);
        } else {
          lineClassNames[highlightedLine] = [className];
        }
      }
    }
  }

  let languageClassName = blockClassName;
  if (language) {
    if (!blockClassName.includes(`language-${language}`)) {
